#ifndef LLM_SIM_ADDRESS_MAPPER_H
#define LLM_SIM_ADDRESS_MAPPER_H

#include <cstdint>
#include <mutex>
#include <string>
#include <unordered_map>
#include <vector>

namespace LLM_SIM_DRAM {

// ---------------------------------------------------------------------------
// AddressMapper
//
// Owner-tracking layer for the DRAM subsystem. Loads the initial DRAM
// ownership map (dram_map.yaml, generated by inst-gen as the single source
// of truth alongside the file_path strings it already emits) and answers
// "which core(s) own this file" queries.
//
// Phase 1 scope: load() + owner_of() only. set_owner()'s atomicity only
// matters once DataManager (and this AddressMapper) become a global
// singleton shared across cores (Phase 2) -- until then each core still has
// its own AddressMapper instance, so there is nothing to race on yet.
// ---------------------------------------------------------------------------
class AddressMapper {
public:
    // Sentinel returned by owner_of() when a path is not present in the
    // loaded map -- treated as "caller-local / not a shared file".
    static constexpr int OWNER_LOCAL = -1;

    AddressMapper() = default;

    // Parses dram_map.yaml at yaml_path and replaces the current table.
    // Throws std::runtime_error on a missing file or malformed schema.
    void load(const std::string& yaml_path);

    // Returns the owner core id for a whole-file match. If the path was
    // recorded with multiple owners ("owners: [...]"), returns the first
    // one -- callers needing the full set should use owners_of().
    // row/col are accepted for future range-level lookups (schema-reserved,
    // see ranges below) but are not consulted yet; whole-file entries match
    // regardless of row/col.
    int owner_of(const std::string& path, int64_t row = 0, int64_t col = 0) const;

    // Returns all owners recorded for path (empty if unmapped).
    std::vector<int> owners_of(const std::string& path) const;

    // True if path has an entry in the loaded map at all.
    bool is_mapped(const std::string& path) const;

    // Phase 7a: true if path's dram_map.yaml entry is tagged
    // kind: initial_kv. Reuses the existing kind field (Phase 1) rather than
    // adding a new schema field -- KV cache write-back-on-eviction semantics
    // needs exactly this weight-vs-KV distinction, and dram_map.yaml already
    // carries it. False for unmapped paths and plain weight entries.
    bool is_initial_kv(const std::string& path) const;

    // schedule_table_sop_refactor: true if path's dram_map.yaml entry is
    // tagged kind: output. Lets test benches locate the final output-tensor
    // file by querying the loaded map instead of hardcoding a filename --
    // gen-time already knows exactly which path is OUTPUT_FILE (dram_map_
    // writer.py's add() call for it), this just exposes that tag at
    // runtime. False for unmapped paths and every other kind (including
    // initial_kv and untagged weight entries).
    bool is_output(const std::string& path) const;

    // Phase E: "logical" element width for
    // path's transfer/storage accounting -- 32 for plain fp32 (default,
    // including every unmapped path), 4 for a path tagged `format: mxfp4` in
    // dram_map.yaml. This is a rough/approximate tag (real MXFP4 averages
    // 4.25 bits/element, ceil(n/32)*17 bytes per 32-element block) --
    // callers needing the EXACT byte count for capacity/latency accounting
    // must use DataManager::logical_bytes(), not `n * elem_bits_of(path) / 8`.
    // elem_bits_of() exists for callers that only need a coarse width (e.g.
    // NoC flit sizing), not appropriate for anything capacity-critical.
    int elem_bits_of(const std::string& path) const;

    // Runtime update: records that core_id now owns path (single owner,
    // replacing any previous entry). Not wired to any call site until
    // Phase 2 promotes DataManager (and this AddressMapper) to a global
    // singleton; safe to call today, just not concurrently meaningful yet.
    void set_owner(const std::string& path, int core_id);

    // (write-time registration for
    // gen-time-unregistered paths): like set_owner(), but ALSO records a
    // format tag derived from elem_bits, for paths dram_map.yaml never
    // mentioned (e.g. a scratch activation the generator forgot to
    // register, or -- the real motivating case -- one whose target path
    // genuinely cannot be enumerated at gen-time). Called from DRAMSim::
    // do_write() ONLY when the path is not already known (elem_bits_of()
    // == 32 AND owners_of() is empty) -- an already gen-time-registered
    // path (K/V cache, weight, ...) is NEVER touched by this, preserving
    // dram_map.yaml as the authoritative source whenever it has an
    // opinion. DataManager/AddressMapper are a single whole-simulation
    // instance (acc_8x8.h: "Single DataManager for the whole simulation"),
    // so a write from any core is immediately visible to every other
    // core's subsequent read of the same path -- no per-core staleness.
    //
    // IMPORTANT INVARIANT (must hold for correctness, NOT enforced by this
    // function): the same path must never be write-registered here with
    // two DIFFERENT elem_bits values across the simulation's lifetime.
    // This function always overwrites entry.format unconditionally on
    // every call (last writer wins, no conflict detection) -- if some
    // future producer legitimately writes the same path at different
    // precisions on different occasions, this silently corrupts the
    // format record for every reader after the second write. Every path
    // this mechanism is intended for today (a same-core scratch tensor
    // written once, read back later) satisfies "one path -> one elem_bits
    // for the whole run" by construction; this is a design precondition
    // to check before pointing this mechanism at any new path, not
    // something this function can verify at runtime.
    void set_owner_and_format(const std::string& path, int core_id, int elem_bits);

    // ── Phase 3a: DRAM group membership (renamed from the prior design
    // doc's "adjacency" -- same 8x8 mesh 4-neighbor semantics, no torus
    // wrap, is_group(a,b) = (|ax-bx| + |ay-by| == 1), ax=a%8, ay=a/8).
    // Deliberately distinct from the unrelated "expert group"
    // (core_id % N_EXPERTS) partition -- do not conflate the two. ─────────

    // Loads a dram_group.bin (fixed 64x64 row-major bitmap, 1 bit per pair,
    // generated by inst-gen from the 4-neighbor formula -- never hand
    // edited, so there is no drift risk). Throws std::runtime_error if the
    // file is missing or the wrong size for num_cores.
    void load_groups(const std::string& bin_path, int num_cores = 64);

    // True if core_a and core_b are in the same DRAM group (may access each
    // other's DRAM). False for core_a == core_b (self is not "grouped with
    // itself" -- local access doesn't go through the group-gated remote
    // path at all) and false if no group bitmap has been loaded.
    bool is_group(int core_a, int core_b) const;

    // Phase C: the num_cores the currently-
    // loaded group bitmap was sized for (0 if load_groups() was never
    // called). Lets DataManager precompute each core's group membership
    // list once at construction (dram_group.bin is static for the whole
    // run) instead of calling is_group() 4x per group-probe on the hot path.
    int num_cores() const;

    // Phase D: enumerate every (path, owners)
    // entry currently in the loaded map, for warm-start LRU seeding. Ranges-
    // only entries (no whole-file owner) are included with an empty owners
    // vector -- callers should skip those, matching owner_of()'s existing
    // "ranges are schema-reserved, not queried" stance. Returns a copy (the
    // map is only ever a few hundred entries and this runs once, at
    // DataManager construction).
    std::vector<std::pair<std::string, std::vector<int>>> all_entries() const;

    // per-owner subset of path's
    // owners that are TP1-base / genuinely-hardware-resident positions (see
    // OwnerEntry::always_resident_owners' doc comment). Empty vector (not
    // an error) if path is unmapped or has no such owners recorded.
    std::vector<int> always_resident_owners_of(const std::string& path) const;

    // init-dram-mapping-dram-fetching-nested-blum plan: per-owner subset of
    // path's owners that should be pre-seeded into DataManager's LRU at
    // every layer's construction (TP4 replica=1/2 shard-cores under
    // gen_prefill_dp_adaptive(tp4_only=True)), but -- unlike
    // always_resident_owners_of() -- remain NORMAL, evictable LRU entries
    // afterwards. See OwnerEntry::warm_seed_owners' doc comment. Empty
    // vector (not an error) if path is unmapped or has no such owners
    // recorded.
    std::vector<int> warm_seed_owners_of(const std::string& path) const;

    // per-owner subset of path's owners
    // that must never be selected as an eviction victim by DataManager::
    // evict_if_needed() -- independent, general-purpose protection flag,
    // NOT tied to any particular fallback mechanism. Motivating case: a
    // core that another core's compile-time miss-fallback table names as
    // its lowest-level-memory target must not have that data evicted out
    // from under it by its own ordinary LRU pressure, or the remote miss
    // fetch that depends on it goes unanswered. Deliberately per-owner
    // (like always_resident_owners/warm_seed_owners) since the same path
    // may have several owners and only the one(s) actually depended upon
    // by a remote fallback need protecting. Empty vector (not an error) if
    // path is unmapped or has no such owners recorded. Callers are
    // responsible for keeping the total protected footprint within
    // capacity -- this mechanism adds no guard against over-protection.
    std::vector<int> no_evict_owners_of(const std::string& path) const;

private:
    struct RangeEntry {
        int64_t row_start, row_end;
        int64_t col_start, col_end;
        int owner;
    };

    struct OwnerEntry {
        std::vector<int> owners;          // whole-file owner(s)
        std::vector<RangeEntry> ranges;    // schema-reserved; not queried yet
        std::string kind;                  // optional tag, e.g. "initial_kv"
        std::string format;                // optional tag, e.g. "mxfp4" (Phase E)
        // per-owner (not
        // per-entry) subset of `owners` that are this path's TP1-base /
        // genuinely-hardware-resident positions, as opposed to an ADP
        // tier-ladder shard/replica position sharing the same base (r=0)
        // file path. See dram_map_writer.py's add()'s always_resident doc
        // comment for the full rationale.
        std::vector<int> always_resident_owners;
        // init-dram-mapping-dram-fetching-nested-blum plan: per-owner
        // subset of `owners` that should be pre-seeded into LRU at every
        // layer's construction, but remain normal evictable entries
        // afterwards -- DELIBERATELY SEPARATE from always_resident_owners
        // (which is permanently exempt from eviction). See dram_map_
        // writer.py's add()'s warm_seed doc comment.
        std::vector<int> warm_seed_owners;
        // per-owner subset of `owners`
        // that must never be evicted by DataManager::evict_if_needed(). See
        // no_evict_owners_of()'s doc comment above.
        std::vector<int> no_evict_owners;
    };

    mutable std::mutex mutex_;
    std::unordered_map<std::string, OwnerEntry> table_;

    // Phase 3a: group bitmap, row-major, bit(a,b) at byte (a*num_cores_g_+b)/8,
    // bit position (a*num_cores_g_+b)%8. Empty if load_groups() was never called.
    mutable std::mutex group_mutex_;
    std::vector<uint8_t> group_bits_;
    int num_cores_g_ = 0;
};

} // namespace LLM_SIM_DRAM

#endif // LLM_SIM_ADDRESS_MAPPER_H
